"use client"

import { useActionState, useEffect, useRef } from "react"
import { useTranslations } from "@/core/i18n/translations"
import { InputField } from "@/shared/forms/fields"
import { Button } from "@/shared/ui/base/button"
import { DialogClose } from "@/shared/ui/base/dialog"
import { FieldError, FieldGroup } from "@/shared/ui/base/field"
import { toast } from "@/shared/ui/base/toast"
import { type AddUserState, addUser } from "../user-commands"
import { useAppRouter } from "@/core/navigation/router"

export function AddUserForm() {
  const t = useTranslations("Members")
  const common = useTranslations("Common")
  const [state, action, pending] = useActionState<AddUserState, FormData>(addUser, { status: "idle" })
  const formRef = useRef<HTMLFormElement>(null)
  const router = useAppRouter()

  useEffect(() => {
    if (state.status === "success" || state.status === "email-failed") {
      formRef.current?.reset()
      router.refresh()
      if (state.status === "success") {
        toast.add({
          type: "success",
          title: t("inviteSent"),
          description: t("inviteSentDescription", { email: state.email })
        })
      } else {
        toast.add({
          type: "warning",
          title: t("inviteNotSent"),
          description: t("inviteNotSentDescription", { email: state.email })
        })
      }
    }
  }, [state, t, router])

  return (
    <form ref={formRef} action={action} className="space-y-6">
      <FieldGroup>
        <InputField label={common("name")} name="name" type="text" autoComplete="name" required />
        <InputField label={common("email")} name="email" type="email" autoComplete="email" required />
        <FieldError>{state.status === "error" ? t(`addErrors.${state.kind}`) : undefined}</FieldError>
      </FieldGroup>
      <div className="flex flex-wrap items-center gap-3">
        <Button type="submit" disabled={pending}>
          {pending ? t("adding") : t("add")}
        </Button>
        <DialogClose render={<Button type="button" variant="ghost" />}>{common("cancel")}</DialogClose>
      </div>
    </form>
  )
}
