"use client"

import { useCallback, useEffect, useState } from "react"
import { authClient } from "@/core/auth/auth-client"
import { useFormatter, useTranslations } from "@/core/i18n/translations"
import { logout } from "@/core/navigation/logout"
import { useAppRouter } from "@/core/navigation/router"
import { ROUTES } from "@/core/navigation/site"
import { Alert, AlertDescription } from "@/shared/ui/base/alert"
import { Badge } from "@/shared/ui/base/badge"
import { Button } from "@/shared/ui/base/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/ui/base/card"

type Session = NonNullable<Awaited<ReturnType<typeof authClient.listSessions>>["data"]>[number]

export function SessionsSettings({ currentSessionToken }: { currentSessionToken: string }) {
  const router = useAppRouter()
  const t = useTranslations("AccountSettings")
  const common = useTranslations("Common")
  const format = useFormatter()
  const [sessions, setSessions] = useState<Session[]>([])
  const [error, setError] = useState<string>()
  const [pendingToken, setPendingToken] = useState<string>()

  const loadSessions = useCallback(async () => {
    setError(undefined)
    const result = await authClient.listSessions()
    if (result.data) setSessions(result.data)
    if (result.error) setError(t("sessionsLoadFailed"))
  }, [t])

  useEffect(() => {
    void loadSessions()
  }, [loadSessions])

  async function revoke(token: string) {
    setPendingToken(token)
    setError(undefined)
    try {
      const current = token === currentSessionToken
      const result = current ? await logout() : await authClient.revokeSession({ token })
      if (result.error) setError(t("sessionRevokeFailed"))
      else if (current) await router.sessionChanged(ROUTES.login)
      else await loadSessions()
    } catch {
      setError(t("sessionRevokeFailed"))
    } finally {
      setPendingToken(undefined)
    }
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t("sessionsTitle")}</CardTitle>
        <CardDescription>{t("sessionsDescription")}</CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        {sessions.map((session) => {
          const current = session.token === currentSessionToken
          return (
            <div key={session.token} className="flex flex-col gap-4 rounded-2xl border p-4">
              <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                <div className="flex flex-wrap items-center gap-2">
                  <p className="wrap-break-word font-medium">{session.userAgent || t("unknownDevice")}</p>
                  {current ? <Badge variant="secondary">{t("thisDevice")}</Badge> : null}
                </div>
                <Button
                  type="button"
                  variant={current ? "outline" : "destructive"}
                  size="sm"
                  onClick={() => void revoke(session.token)}
                  disabled={pendingToken === session.token}
                >
                  {pendingToken === session.token ? t("signingOut") : current ? t("signOut") : common("delete")}
                </Button>
              </div>
              <div className="flex flex-wrap gap-x-6 gap-y-2 border-t pt-3 text-sm text-muted-foreground">
                <p>
                  <span className="font-medium text-foreground">{t("ipAddress")}</span>{" "}
                  {session.ipAddress || t("unknown")}
                </p>
                <p>
                  <span className="font-medium text-foreground">{t("expires")}</span>{" "}
                  {format.dateTime(session.expiresAt, { dateStyle: "medium", timeStyle: "short" })}
                </p>
              </div>
            </div>
          )
        })}
        {sessions.length === 0 ? <p className="text-sm text-muted-foreground">{t("noSessions")}</p> : null}
        {error ? (
          <Alert variant="destructive">
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        ) : null}
      </CardContent>
    </Card>
  )
}
