"use client"

import { useForm, useSelector } from "@tanstack/react-form"
import { useState } from "react"
import type z from "zod"
import { useTranslations } from "@/core/i18n/translations"
import { getPostLoginPath, twoFactorPath } from "@/core/navigation/navigation-utils"
import { ROUTES } from "@/core/navigation/site"
import { InputField } from "@/shared/forms/fields"
import { Alert, AlertDescription } from "@/shared/ui/base/alert"
import { Button } from "@/shared/ui/base/button"
import { Checkbox } from "@/shared/ui/base/checkbox"
import { Field, FieldGroup, FieldLabel } from "@/shared/ui/base/field"
import { Spinner } from "@/shared/ui/base/spinner"
import { loginSchema } from "./schemas"
import { type LoginResult, signInWithIdentifier, signInWithPasskey } from "./service"
import { Link, useAppRouter, useSearchParams } from "@/core/navigation/router"

export function LoginForm() {
  const t = useTranslations("Public.login")
  const router = useAppRouter()
  const searchParams = useSearchParams()
  const returnTo = searchParams.get("returnTo") ?? undefined
  const [formError, setFormError] = useState<string | null>(null)
  const [isPasskeySubmitting, setIsPasskeySubmitting] = useState(false)

  function completeSignIn(result: LoginResult) {
    if (!result.success) {
      if ("requiresTwoFactor" in result) {
        router.replace(twoFactorPath(result.methods, returnTo))
        return
      }
      setFormError(t(`errors.${result.error}`))
      return
    }

    router.sessionChanged(getPostLoginPath(result.role, returnTo))
  }

  async function handlePasskeySignIn() {
    setFormError(null)

    setIsPasskeySubmitting(true)
    const result = await signInWithPasskey()
    setIsPasskeySubmitting(false)
    completeSignIn(result)
  }

  async function onSubmit({ value }: { value: z.infer<typeof loginSchema> }) {
    setFormError(null)

    const result = await signInWithIdentifier({
      identifier: value.identifier,
      password: value.password,
      rememberMe: value.rememberMe
    })
    completeSignIn(result)
  }

  const form = useForm({
    defaultValues: {
      identifier: "",
      password: "",
      rememberMe: false
    },
    validators: {
      onSubmit: loginSchema
    },
    onSubmit
  })
  const isSubmitting = useSelector(form.store, (state) => state.isSubmitting)

  return (
    <form
      id="login-form"
      onSubmit={(e) => {
        e.preventDefault()
        form.handleSubmit()
      }}
      aria-busy={isSubmitting}
      className="flex flex-col gap-4"
    >
      <FieldGroup>
        <form.Field name="identifier">
          {(field) => {
            const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
            return (
              <InputField
                label={t("identifier")}
                name={field.name}
                value={field.state.value}
                onBlur={field.handleBlur}
                onChange={(e) => field.handleChange(e.target.value)}
                placeholder={t("identifier")}
                autoComplete="username"
                invalid={isInvalid}
                errors={isInvalid ? field.state.meta.errors : undefined}
              />
            )
          }}
        </form.Field>
        <form.Field name="password">
          {(field) => {
            const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
            return (
              <InputField
                label={t("password")}
                name={field.name}
                type="password"
                value={field.state.value}
                onBlur={field.handleBlur}
                onChange={(e) => field.handleChange(e.target.value)}
                placeholder={t("password")}
                autoComplete="current-password"
                invalid={isInvalid}
                errors={isInvalid ? field.state.meta.errors : undefined}
              />
            )
          }}
        </form.Field>
        <form.Field name="rememberMe">
          {(field) => {
            return (
              <Field orientation="horizontal">
                <Checkbox
                  id={field.name}
                  name={field.name}
                  checked={field.state.value}
                  onCheckedChange={(checked) => field.handleChange(checked)}
                />
                <FieldLabel htmlFor={field.name} className="font-normal">
                  {t("rememberMe")}
                </FieldLabel>
              </Field>
            )
          }}
        </form.Field>
      </FieldGroup>
      {formError && (
        <Alert variant="destructive">
          <AlertDescription>{formError}</AlertDescription>
        </Alert>
      )}
      <Button type="submit" disabled={isSubmitting}>
        {isSubmitting ? (
          <>
            <Spinner />
            {t("submitting")}
          </>
        ) : (
          t("submit")
        )}
      </Button>
      <div className="relative flex items-center justify-center">
        <span className="absolute inset-x-0 border-t" />
        <span className="relative bg-background px-2 text-muted-foreground text-xs">{t("or")}</span>
      </div>
      <Button
        type="button"
        variant="outline"
        onClick={handlePasskeySignIn}
        disabled={isSubmitting || isPasskeySubmitting}
      >
        {isPasskeySubmitting ? t("passkeyPending") : t("passkey")}
      </Button>
      <Link href={ROUTES.forgotPassword} className="text-center text-sm underline underline-offset-4">
        {t("forgotPassword")}
      </Link>
    </form>
  )
}
