"use client"

import { PlusIcon, XIcon } from "lucide-react"
import { type ReactNode, useActionState, useState } from "react"
import { useTranslations } from "@/core/i18n/translations"
import { conversationPath } from "@/core/navigation/navigation-utils"
import { Button } from "@/shared/ui/base/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger
} from "@/shared/ui/base/dialog"
import { Input } from "@/shared/ui/base/input"
import { Textarea } from "@/shared/ui/base/textarea"
import { MAX_GROUP_NAME_LENGTH } from "../../model/group-conversation"
import { MAX_MESSAGE_BODY_LENGTH } from "../../model/message-body"
import { startConversationCommand } from "../api-commands"
import { createMessageIdempotencyKey } from "../composer/idempotency-key"
import type { MessageCommandState } from "../composer/message-command-state"
import { MemberSelection, type SelectedMember } from "../member-selection"
import { useAppRouter } from "@/core/navigation/router"

const initialState: MessageCommandState = { status: "idle" }
/** Opens the shared composer, optionally with a member selected from their profile. */
export function StartConversationDialog({
  initialMember,
  children
}: {
  initialMember?: SelectedMember
  children?: ReactNode
}) {
  const t = useTranslations("Messages")
  const ui = useTranslations("Ui")
  const [open, setOpen] = useState(false)
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger
        render={
          children ? (
            <Button type="button" />
          ) : (
            <Button type="button" variant="outline" size="icon" aria-label={t("startTitle")} title={t("startTitle")} />
          )
        }
      >
        {children ?? <PlusIcon aria-hidden="true" />}
      </DialogTrigger>
      <DialogContent showCloseButton={false} className="max-h-[calc(100dvh-2rem)] overflow-y-auto">
        <DialogHeader className="pr-8">
          <DialogTitle>{t("startTitle")}</DialogTitle>
          <DialogDescription>{t("startCombinedDescription")}</DialogDescription>
        </DialogHeader>
        <DialogClose
          render={
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              className="absolute right-4 top-4"
              aria-label={ui("close")}
            />
          }
        >
          <XIcon aria-hidden="true" />
        </DialogClose>
        <StartConversationForm initialMember={initialMember} onStarted={() => setOpen(false)} />
      </DialogContent>
    </Dialog>
  )
}

function StartConversationForm({
  initialMember,
  onStarted
}: {
  initialMember?: SelectedMember
  onStarted: () => void
}) {
  const t = useTranslations("Messages")
  const router = useAppRouter()
  const [selected, setSelected] = useState<SelectedMember[]>(initialMember ? [initialMember] : [])
  const [idempotencyKey, setIdempotencyKey] = useState(createMessageIdempotencyKey)
  const [name, setName] = useState("")
  const [text, setText] = useState("")
  const [state, action, pending] = useActionState(async (previous: MessageCommandState, formData: FormData) => {
    const result = await startConversationCommand(previous, formData)
    if (result.status === "success") {
      // Activity restores effects on browser Back; navigate only when this submission completes.
      onStarted()
      router.push(conversationPath(result.conversationId))
    }
    return result
  }, initialState)
  const isGroup = selected.length > 1
  return (
    <form action={action} className="grid gap-3">
      <input type="hidden" name="idempotencyKey" value={idempotencyKey} />
      <MemberSelection
        value={selected}
        disabled={pending}
        onChange={(members) => {
          setSelected(members)
          setIdempotencyKey(createMessageIdempotencyKey())
        }}
      />
      {selected.length ? (
        <p className="text-sm text-muted-foreground" role="status">
          {t(isGroup ? "groupConversationMode" : "directConversationMode")}
        </p>
      ) : null}
      {isGroup ? (
        <Input
          name="name"
          aria-label={t("groupName")}
          placeholder={t("groupName")}
          value={name}
          onChange={(event) => {
            setName(event.target.value)
            setIdempotencyKey(createMessageIdempotencyKey())
          }}
          required
          maxLength={MAX_GROUP_NAME_LENGTH}
          disabled={pending}
        />
      ) : selected.length === 1 ? (
        <Textarea
          name="text"
          aria-label={t("firstMessageLabel")}
          placeholder={t("messagePlaceholder")}
          value={text}
          onChange={(event) => setText(event.target.value)}
          required
          maxLength={MAX_MESSAGE_BODY_LENGTH}
          disabled={pending}
        />
      ) : null}
      {state.status === "error" ? (
        <p className="text-sm text-destructive" role="alert">
          {t(state.error === "unexpected" ? "startConversationFailed" : `errors.${state.error}`)}
        </p>
      ) : null}
      <Button
        type="submit"
        className="w-fit max-w-full whitespace-normal"
        disabled={pending || selected.length === 0 || (isGroup ? !name.trim() : !text.trim())}
      >
        {pending ? t("starting") : t(isGroup ? "createGroup" : "sendMessage")}
      </Button>
    </form>
  )
}
